from rules import SOLVERS


def solve(data):
    return {component_id: solver(data[component_id])
            for component_id, solver in SOLVERS.items()}

def _round(numerator, denominator, mode):
    if mode == "half_up":
        return (numerator + denominator // 2) // denominator
    return numerator // denominator


def _ledger(data, revision_priority, tax_base):
    chosen = {}
    cutoff = data.get("cutoff", 10**9)
    for position, event in enumerate(data["events"]):
        sequence = event.get("sequence", 0)
        if sequence > cutoff:
            continue
        event_id = event.get("id", "anonymous:" + str(position))
        if revision_priority == "sequence_first":
            key = (sequence, event.get("revision", 0), position)
        else:
            key = (event.get("revision", 0), position)
        if event_id not in chosen or key > chosen[event_id][0]:
            chosen[event_id] = (key, event)

    balances = dict(data.get("opening", {}))
    mode = data["rounding"]
    for _, event in chosen.values():
        if event.get("void", False):
            continue
        raw = event["price"] * event.get("quantity", 1)
        discount = min(10000, max(0, event.get("discount_bp", 0)))
        net = _round(raw * (10000 - discount), 10000, mode)
        base = net if tax_base == "discounted" else raw
        tax = _round(base * event.get("tax_bp", 0), 10000, mode)
        total = net + tax
        if event.get("kind") == "refund":
            total = -total
        key = event.get("account", "default") + "|" + event.get("currency", "USD")
        balances[key] = balances.get(key, 0) + total
    return {"balances": balances}


def _dependency_resolver(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    choices = {}
    for name in names:
        versions = [row["version"] for row in packages[name]
                    if row["version"] not in blocked.get(name, [])
                    and (name not in pins or row["version"] == pins[name])]
        choices[name] = [None] + sorted(versions)

    roots = data["roots"]
    assignment = {}
    best_vector = None
    best = None

    def check():
        edges = {}
        for name, version in assignment.items():
            row = next(row for row in packages[name] if row["version"] == version)
            active = []
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                active.append(dep)
            edges[name] = active

        for name, (low, high) in roots.items():
            if name not in assignment or not low <= assignment[name] <= high:
                return False
        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            if name not in assignment:
                return False
            reachable.add(name)
            for dep in edges[name]:
                other = dep["name"]
                if other not in assignment or not dep["min"] <= assignment[other] <= dep["max"]:
                    return False
                stack.append(other)
        if reachable != set(assignment):
            return False

        state = {}
        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            for dep in edges[name]:
                if not visit(dep["name"]):
                    return False
            state[name] = 2
            return True
        return all(visit(name) for name in assignment)

    def search(index):
        nonlocal best_vector, best
        if index == len(names):
            if check():
                vector = tuple(assignment.get(name, -1) for name in names)
                if best_vector is None or vector > best_vector:
                    best_vector = vector
                    best = dict(assignment)
            return
        name = names[index]
        for version in choices[name]:
            if version is None:
                assignment.pop(name, None)
            else:
                assignment[name] = version
            search(index + 1)
        assignment.pop(name, None)

    search(0)
    if best is None:
        return {"error": "unsatisfiable"}
    return {"versions": best}


def _quota_intervals(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    quotas = data.get("quotas", {})
    options = [job for job in jobs if job["id"] not in blocked]
    best_value = None
    best_ids = None

    def valid(selected):
        ids = {job["id"] for job in selected}
        if not mandatory <= ids:
            return False
        counts = {}
        for job in selected:
            group = job["group"]
            counts[group] = counts.get(group, 0) + 1
        for group, (low, high) in quotas.items():
            if not low <= counts.get(group, 0) <= high:
                return False
        active = []
        for job in sorted(selected, key=lambda item: (item["start"], item["end"])):
            active = [end for end in active if end > job["start"]]
            active.append(job["end"])
            if len(active) > 2:
                return False
        return True

    def enumerate_subsets(index, selected):
        nonlocal best_value, best_ids
        if len(selected) > k or len(selected) + len(options) - index < k:
            return
        if index == len(options):
            if len(selected) != k or not valid(selected):
                return
            value = sum(job["value"] for job in selected)
            ids = tuple(sorted(job["id"] for job in selected))
            if (best_value is None or value > best_value
                    or (value == best_value and ids < best_ids)):
                best_value, best_ids = value, ids
            return
        enumerate_subsets(index + 1, selected)
        enumerate_subsets(index + 1, selected + [options[index]])

    enumerate_subsets(0, [])
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": list(best_ids), "value": best_value}


def _temporal_routes(data):
    import heapq

    required = data.get("required", [])
    bit = {node: 1 << i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    start_node = data["source"]
    initial_mask = bit.get(start_node, 0)
    start_time = data["start"]
    initial = (start_node, initial_mask, 0)
    distances = {initial: start_time}
    queue = [(start_time, start_node, initial_mask, 0)]
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    while queue:
        time, node, mask, used = heapq.heappop(queue)
        state = (node, mask, used)
        if distances.get(state) != time:
            continue
        if node == data["target"] and mask == full:
            return {"arrival": time}
        for edge in graph[node]:
            depart = max(time, edge["open"])
            if depart >= edge["close"]:
                continue
            options = [(edge["duration"], used)]
            if used < data["coupons"]:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                options.append((duration, used + 1))
            for duration, next_used in options:
                arrival = depart + duration
                if arrival > data["deadline"]:
                    continue
                next_node = edge["v"]
                next_mask = mask | bit.get(next_node, 0)
                next_state = (next_node, next_mask, next_used)
                if arrival < distances.get(next_state, float("inf")):
                    distances[next_state] = arrival
                    heapq.heappush(queue, (arrival, next_node, next_mask, next_used))
    return {"arrival": None}


SOLVERS = {
    "component_01": lambda data: _ledger(data, "revision_first", "discounted"),
    "component_02": lambda data: _ledger(data, "sequence_first", "discounted"),
    "component_03": lambda data: _ledger(data, "revision_first", "original"),
    "component_04": lambda data: _ledger(data, "sequence_first", "original"),
    "component_05": lambda data: _ledger(data, "revision_first", "discounted"),
    "component_06": _dependency_resolver,
    "component_07": _quota_intervals,
    "component_08": _temporal_routes,
}
